import os,json,subprocess
from pathlib import Path
unit=Path("/etc/systemd/system/lowcost-europa.service")
root=Path("/srv/projects/lowcost-europa")
old="/etc/lowcost-europa/lowcost-europa.env";new="/srv/projects/lowcost-europa/private/systemd-env/lowcost-europa.env"
out={"project":"lowcost-europa","status":"BLOCKED","changed":False}
def cmd(args):
 r=subprocess.run(args,capture_output=True,text=True,timeout=15);return r.returncode,r.stdout.strip()
def service():
 return {p:cmd(["systemctl","show","lowcost-europa","-p",p,"--value"])[1] for p in ("ActiveState","MainPID")}
replaced=False
try:
 if not unit.is_file() or unit.is_symlink() or not root.is_dir() or root.is_symlink() or not Path(new).is_file() or Path(new).is_symlink():raise RuntimeError("unit_or_env_preflight")
 content=unit.read_bytes();st=unit.stat()
 if content.count(old.encode())!=1 or new.encode() in content:raise RuntimeError("expected_old_reference_missing")
 previous=service()
 archive=root/"archive"/"systemd-config"
 archive.mkdir(mode=0o700,parents=True,exist_ok=True)
 backup=archive/"lowcost-europa.service.pre-canonical-20261104"
 with open(backup,"xb") as f:f.write(content);f.flush();os.fsync(f.fileno())
 os.chmod(backup,0o600)
 tmp=unit.with_name(".lowcost-europa.service.canonical.tmp")
 with open(tmp,"xb") as f:f.write(content.replace(old.encode(),new.encode()));f.flush();os.fsync(f.fileno())
 os.chown(tmp,st.st_uid,st.st_gid);os.chmod(tmp,st.st_mode&0o777)
 os.replace(tmp,unit);replaced=True
 if cmd(["systemd-analyze","verify",str(unit)])[0]!=0:raise RuntimeError("unit_verification_failed")
 if cmd(["systemctl","daemon-reload"])[0]!=0:raise RuntimeError("daemon_reload_failed")
 if service()!=previous:raise RuntimeError("service_restart_or_state_change")
 if unit.read_bytes().count(new.encode())!=1 or old.encode() in unit.read_bytes():raise RuntimeError("readback_reference_mismatch")
 out.update(status="UPDATED_VERIFIED",changed=True,new_unit_env_path=new,previous_pid_preserved=True,systemd_verify=True,daemon_reload=True,backup_in_project=True)
except Exception as e:
 out["reason"]=str(e)[:140]
 if replaced:
  try:
   tmp=unit.with_name(".lowcost-europa.service.rollback.tmp")
   with open(tmp,"xb") as f:f.write(content);f.flush();os.fsync(f.fileno())
   os.chown(tmp,st.st_uid,st.st_gid);os.chmod(tmp,st.st_mode&0o777)
   os.replace(tmp,unit);cmd(["systemctl","daemon-reload"])
   out["rollback"]="RESTORED"
  except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="UPDATED_VERIFIED":raise SystemExit(3)
